INSERT INTO `role_capabilities` (`role_code`,`capability_code`,`created_at`) SELECT r.`code`,c.`code`,UTC_TIMESTAMP(3) FROM `roles` r JOIN `capabilities` c WHERE r.`code`='platform_super_admin' OR (r.`code`='organization_admin' AND c.`code` NOT LIKE 'platform:%' AND c.`code` NOT IN ('session:manage','platform_token:manage','key_rotation:manage','collection:replay')) OR (r.`code`='member' AND c.`code` IN ('task:read','task:create','task:update','trend:read','opportunity:read','opportunity:decide','competitor:read','sourcing:read','notification:read')) OR (r.`code`='selection_manager' AND c.`code` IN ('task:read','task:create','task:update','task:assign','trend:read','opportunity:read','opportunity:decide','opportunity:approve','competitor:read','sourcing:read','notification:read','team:manage','report:read')) OR (r.`code`='procurement_member' AND c.`code` IN ('task:read','task:update','opportunity:read','sourcing:read','supplier_quote:manage','cost:confirm','notification:read')) OR (r.`code`='platform_operations_admin' AND c.`code` IN ('platform:operate','task:read','trend:read','opportunity:read','competitor:read','sourcing:read','provider:configure','collection:replay','report:read')) OR (r.`code`='platform_security_admin' AND c.`code` IN ('platform:secure','task:read','trend:read','opportunity:read','competitor:read','sourcing:read','session:manage','platform_token:manage','audit:read','key_rotation:manage')) OR (r.`code`='auditor' AND c.`code` IN ('task:read','trend:read','opportunity:read','competitor:read','sourcing:read','audit:read','report:read','role:read','membership:read'));
